import { useState } from "react";

const Predefined = () => {
  const [selectedPattern, setSelectedPattern] = useState("");
  const [isLoading, setIsLoading] = useState(false);

  // Define available patterns
  const patterns = [
    { id: 1, name: "Rain Effect", description: "Falling droplets animation" },
    { id: 2, name: "Spiral", description: "Rotating spiral pattern" },
    { id: 3, name: "Wave", description: "Sine wave animation" },
    { id: 4, name: "Explosion", description: "Center outward burst" },
    { id: 5, name: "Snake", description: "Moving snake pattern" },
    { id: 6, name: "Fireworks", description: "Random bursts of light" },
    { id: 7, name: "Breathing", description: "Fade in/out effect" },
    { id: 8, name: "Matrix Rain", description: "Digital rain effect" },
    { id: 9, name: "Cube Rotate", description: "Rotating cube outline" },
    { id: 10, name: "Random Sparkle", description: "Random LED twinkle" }
  ];

  const handleSubmit = async () => {
    if (!selectedPattern) {
      alert("Please select a pattern first!");
      return;
    }

    setIsLoading(true);
    
    try {
      console.log("Sending pattern:", selectedPattern);
      
      const data = {
        pattern: parseInt(selectedPattern),
        timestamp: Date.now()
      };

      const result = await fetch("http://localhost:3000/send-pattern", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(data),
      });

      if (result.ok) {
        const response = await result.json();
        console.log("Pattern sent successfully:", response);
        alert(`Pattern ${selectedPattern} sent to cube!`);
      } else {
        throw new Error(`HTTP error! status: ${result.status}`);
      }
    } catch (error) {
      console.error("Error sending pattern:", error);
      alert("Failed to send pattern to cube. Please check connection.");
    } finally {
      setIsLoading(false);
    }
  };

  const handlePatternChange = (e) => {
    setSelectedPattern(e.target.value);
  };

  const selectedPatternInfo = patterns.find(p => p.id === parseInt(selectedPattern));

  return (
    <div style={styles.container}>
      <div style={styles.formContainer}>
        <h2 style={styles.title}>LED Cube Pattern Control</h2>
        
        <div style={styles.form}>
          <label htmlFor="patternSelect" style={styles.label}>
            Select Pattern:
          </label>
          
          <select
            id="patternSelect"
            name="patternSelect"
            value={selectedPattern}
            onChange={handlePatternChange}
            style={styles.select}
            disabled={isLoading}
          >
            <option value="">-- Choose a Pattern --</option>
            {patterns.map((pattern) => (
              <option key={pattern.id} value={pattern.id}>
                {pattern.id}. {pattern.name}
              </option>
            ))}
          </select>

          {selectedPatternInfo && (
            <div style={styles.patternInfo}>
              <h4 style={styles.patternName}>{selectedPatternInfo.name}</h4>
              <p style={styles.patternDescription}>{selectedPatternInfo.description}</p>
            </div>
          )}

          <button 
            onClick={handleSubmit}
            style={{
              ...styles.button,
              ...(isLoading ? styles.buttonDisabled : {})
            }}
            disabled={isLoading}
          >
            {isLoading ? "Sending..." : "Send to Cube"}
          </button>
        </div>

        <div style={styles.patternGrid}>
          <h3 style={styles.gridTitle}>Available Patterns:</h3>
          <div style={styles.grid}>
            {patterns.map((pattern) => (
              <div 
                key={pattern.id} 
                style={{
                  ...styles.patternCard,
                  ...(parseInt(selectedPattern) === pattern.id ? styles.selectedCard : {})
                }}
                onClick={() => setSelectedPattern(pattern.id.toString())}
              >
                <div style={styles.patternNumber}>{pattern.id}</div>
                <div style={styles.cardName}>{pattern.name}</div>
                <div style={styles.cardDescription}>{pattern.description}</div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

const styles = {
  container: {
    fontFamily: "Arial, sans-serif",
    backgroundColor: "#f0f2f5",
    minHeight: "100vh",
    padding: "20px",
  },
  formContainer: {
    maxWidth: "800px",
    margin: "0 auto",
  },
  title: {
    textAlign: "center",
    color: "#333",
    marginBottom: "30px",
    fontSize: "28px",
  },
  form: {
    backgroundColor: "white",
    padding: "30px",
    borderRadius: "10px",
    boxShadow: "0 4px 12px rgba(0, 0, 0, 0.1)",
    marginBottom: "30px",
  },
  label: {
    display: "block",
    marginBottom: "10px",
    fontWeight: "bold",
    fontSize: "16px",
    color: "#333",
  },
  select: {
    width: "100%",
    padding: "12px",
    marginBottom: "20px",
    border: "2px solid #ddd",
    borderRadius: "5px",
    fontSize: "16px",
    backgroundColor: "white",
    cursor: "pointer",
  },
  patternInfo: {
    backgroundColor: "#e3f2fd",
    padding: "15px",
    borderRadius: "5px",
    marginBottom: "20px",
    border: "1px solid #bbdefb",
  },
  patternName: {
    margin: "0 0 8px 0",
    color: "#1976d2",
    fontSize: "18px",
  },
  patternDescription: {
    margin: "0",
    color: "#666",
    fontSize: "14px",
  },
  button: {
    width: "100%",
    padding: "12px 20px",
    fontSize: "18px",
    backgroundColor: "#007bff",
    color: "white",
    border: "none",
    borderRadius: "5px",
    cursor: "pointer",
    transition: "background-color 0.3s",
  },
  buttonDisabled: {
    backgroundColor: "#ccc",
    cursor: "not-allowed",
  },
  patternGrid: {
    backgroundColor: "white",
    padding: "30px",
    borderRadius: "10px",
    boxShadow: "0 4px 12px rgba(0, 0, 0, 0.1)",
  },
  gridTitle: {
    marginBottom: "20px",
    color: "#333",
    textAlign: "center",
  },
  grid: {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))",
    gap: "15px",
  },
  patternCard: {
    padding: "15px",
    border: "2px solid #e0e0e0",
    borderRadius: "8px",
    cursor: "pointer",
    transition: "all 0.3s ease",
    backgroundColor: "#fafafa",
    textAlign: "center",
  },
  selectedCard: {
    borderColor: "#007bff",
    backgroundColor: "#e3f2fd",
    transform: "scale(1.02)",
  },
  patternNumber: {
    fontSize: "24px",
    fontWeight: "bold",
    color: "#007bff",
    marginBottom: "8px",
  },
  cardName: {
    fontSize: "16px",
    fontWeight: "bold",
    color: "#333",
    marginBottom: "5px",
  },
  cardDescription: {
    fontSize: "12px",
    color: "#666",
  },
};

export default Predefined;
